<script lang="ts">import { createApiClient } from '$lib/api/index'; let { data }=$props(); let busy=$state<string|null>(null); async function pdf(i:any){busy=i.studentId;try{const b=await createApiClient(data.token).getBlob(`/psychological-reports/${i.assignmentId}/${i.studentId}/download`);const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='laporan-psikologis.pdf';a.click();URL.revokeObjectURL(u)}finally{busy=null}}</script><h2>Laporan Psikologis Siswa</h2><p>Hanya siswa dari sekolah Anda yang ditampilkan.</p><div class="list">{#each data.reports.items as i}<article><div><strong>{i.studentName}</strong><span>{i.schoolName}</span></div><button onclick={()=>pdf(i)}>{busy===i.studentId?'Menyiapkan…':'Unduh PDF'}</button></article>{/each}</div><style>p,span{color:var(--lp-ink-2)}.list{display:grid;gap:.75rem}article{display:flex;justify-content:space-between;border:1px solid var(--lp-rule);padding:1rem;border-radius:.75rem}article div{display:grid}button{border:0;border-radius:.5rem;background:var(--lp-accent-deep);color:#fff;padding:.5rem .75rem}</style>
